#!/usr/bin/env python3
# Phase 437: CLAUDE.md -- the phase log row.
import sys, re
p = sys.argv[1]; s = open(p, encoding='utf-8').read()
ROW = """| 437 | 2026-10-12 | **Chapter 11 (Tones & Semitones, was 7) complete: the Lesson Book final, on screen, the drill, the Workbook, the Teacher copy.** Her 12:53 '계속 진행하자' -- the v2 pack's B answers as recommended (B2-B11; B6 the natural goes to the Accidentals room). Book: the yellow marks gone; page 3's pairs name no sharps before page 5 ('the big house's first and second black keys, the small house's second black key with E'); Korean page 3 ends with a verb. On screen (TnLearn, the book as the lesson, TN_STORE keeps the old ticks): TnHalf (a key's half steps light up; the half-step walk C to C), TnSteps (count the half steps between two keys), TnWhites (white neighbours, whole or half), TnSharpFlat (♯ up / ♭ down from a white key; no E♯ B♯ F♭ C♭), TnStaffPlay (the book's eight notes: tap to hear and see the key). Drill TN_LEVELS: 1 half or whole (either name) · 2 play a half step · 3 play a whole step · 4 white neighbours · 5 name the black keys · 6 one key, two names · 7 sharps and flats on the staff (pitch class); levels 5-6 never mix the signs. Workbook TnWorkbook (6 pages, English, set tasks a child can do alone; TnPKeys: your key tinted coral, printed circles on black keys to fill in) and TnPaperCheck; Teacher copy TnTeacher (enharmonic and chromatic named here; H/W = S/T). A second reviewer checked every answer, 4,000 drill questions a level, the Book rules and the Korean; fixed: E♯ and C♭ staff items, sharps before page 5, Teacher numbers, the staff sound an octave high, B on TnWhites, the circles count, the check-up's last task, whole-step arrows, the page 5 puzzle ('same key or not?'). Review pack: Claude outputs/Chapter-11-Tones-Semitones-review-v3.pdf (G1-G3 for the guide page, keep-all, A8 still open). Also shown today: room objects instead of frames (A frame, B glass dome -- recommended, C window, D oval medallion, E fireplace, F no frame), waiting on her pick. Checks: tn437test 11/11, wbcheck tones no overflow (work en/ko, teacher, spread, lesson), lbcheck tones 0/0. |
"""
m = re.search(r'^\| 436 \| [^\n]*\n', s, re.M)
if not m: raise SystemExit('row 436')
s = s[:m.end()] + ROW + s[m.end():]
open(p, 'w', encoding='utf-8').write(s); print('CLAUDE.md: log row 437')
